INSERT OVERWRITE TABLE ${schema}.dwm_sr_data_warehouse_homepage_user_item
PARTITION (grass_region = ${grass_region}, local_date = ${local_date}, operation)
SELECT
    platform
    ,user_id
    ,app_version
    ,regexp_extract(app_version, '(.+)(\\.)(.+)', 1) AS major_app_version
    ,item_id
    ,is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,reporting_module AS module
    ,source1_reporting_module AS source1_module
    ,source2_reporting_module AS source2_module
    ,reporting_object AS object
    ,source1_reporting_object AS source1_object
    ,source2_reporting_object AS source2_object
    ,SUM(if(operation='view', operation_cnt, 0)) AS view_cnt
    ,SUM(if(operation='impression', operation_cnt, 0)) AS imp_cnt
    ,SUM(if(operation='click', operation_cnt, 0)) AS click_cnt
    ,SUM(if(operation='omni_impression', operation_cnt, 0)) AS omni_imp_cnt
    ,SUM(if(operation='omni_click', operation_cnt, 0)) AS omni_click_cnt
    ,SUM(if(operation='ppv' and is_back=FALSE, operation_cnt, 0)) AS ppv_cnt
    ,SUM(if(operation='cart', operation_cnt, 0)) AS cart_cnt
    ,SUM(if(operation='order', operation_cnt, 0)) AS order_cnt
    ,SUM(place_order_gmv_local) AS gmv_local
    ,SUM(place_order_gmv) AS gmv
    ,SUM(page_stay_duration) AS page_stay_duration
    ,sum(pc2_gmv_local) as pc2_gmv_local
    ,sum(pc2_gmv) as  pc2_gmv
    ,max(location) as location
    ,card_type
    ,sum(case when operation  = 'impression' and get_eventtype_and_cardtype(feature_detail, operation)[1] ='1' then operation_cnt else 0 end ) as item_imp_cnt
    ,sum(case when operation  = 'click' and get_eventtype_and_cardtype(feature_detail, operation)[1] ='1' then operation_cnt else 0 end ) as item_click_cnt
    ,sum(if(operation = 'impression' and page_type = 'home' and target_type <> 'animation_text' , operation_cnt, 0)) as hp_imp_cnt
    ,sum(if(operation = 'view' and page_type = 'home' , operation_cnt, 0)) as hp_view_cnt
    ,sum(if(original_operation = 'stay_view' and page_type = 'home' , page_stay_duration, 0)) as hp_duration
    ,sum(if(original_operation = 'action_scroll_down' and page_type = 'home', 1, 0)) as hp_is_scrolldown
    ,sum(if(original_page_type = 'product', page_stay_duration, 0)) as product_page_stay_duration

    ,operation
FROM srdi_mart.dwd_sr_data_warehouse_platform
WHERE grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation IN (${operation})
    AND (page_type = 'home' OR source1_page_type = 'home' OR source2_page_type = 'home')
GROUP BY platform
    ,user_id
    ,app_version
    ,item_id
    ,is_ads
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,operation
    ,card_type
    ,reporting_module
    ,source1_reporting_module
    ,source2_reporting_module
    ,reporting_object
    ,source1_reporting_object
    ,source2_reporting_object
